/* prog33_mod_pow.c
 * Reimplementation of the original binary's observable behaviour.
 *
 * Usage:
 *   prog33_mod_pow <base> <exponent> <modulus>
 *
 * Prints one of the following messages on stdout:
 *   NO_INPUT
 *   BAD_INPUT
 *   BAD_MODULUS
 *   OUT_OF_RANGE
 *   NEGATIVE_EXPONENT
 *   result=<value>
 *
 * The program returns 0 in all cases.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <inttypes.h>

static int fully_parsed(const char *orig, const char *end) {
    /* strtoll stops at the first character that is not part of the number.
       The argument is considered valid only if the whole string was consumed. */
    return *end == '\0';
}

int main(int argc, char *argv[]) {
    if (argc < 4) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr;
    long long base, exponent, modulus;

    /* Parse base */
    base = strtoll(argv[1], &endptr, 10);
    if (!fully_parsed(argv[1], endptr)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Parse exponent */
    exponent = strtoll(argv[2], &endptr, 10);
    if (!fully_parsed(argv[2], endptr)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Parse modulus */
    modulus = strtoll(argv[3], &endptr, 10);
    if (!fully_parsed(argv[3], endptr)) {
        puts("BAD_INPUT");
        return 0;
    }

    /* Validate modulus */
    if (modulus < 1) {
        puts("BAD_MODULUS");
        return 0;
    }
    if (modulus > 1000000000LL) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* Validate exponent */
    if (exponent < 0) {
        puts("NEGATIVE_EXPONENT");
        return 0;
    }

    /* Modular exponentiation (square‑and‑multiply) */
    long long result = 1 % modulus;          // works for modulus == 1
    long long b = base % modulus;
    if (b < 0) {
        b += modulus;                        // make base non‑negative
    }

    long long e = exponent;
    while (e > 0) {
        if (e & 1LL) {
            __int128 tmp = (__int128)result * b;
            result = (long long)(tmp % modulus);
        }
        __int128 sq = (__int128)b * b;
        b = (long long)(sq % modulus);
        e >>= 1;
    }

    printf("result=%" PRId64 "\n", result);
    return 0;
}
